#[derive(Debug, Clone)]
pub enum ActiveWriteEncryption {
    None,
    SseCustomer {
        encryption: ObjectEncryption,
        write: Option<SseCustomerWriteContext>,
    },
    Managed {
        encryption: ObjectEncryption,
        algorithm: ManagedEncryptionAlgorithm,
        write: Option<ManagedEncryptionWriteContext>,
    },
}

#[derive(Debug, Clone, Copy)]
pub enum ActiveWriteEncryptionRef<'a> {
    None,
    SseCustomer(&'a SseCustomerWriteContext),
    Managed {
        algorithm: ManagedEncryptionAlgorithm,
        write: &'a ManagedEncryptionWriteContext,
    },
}

impl ActiveWriteEncryption {
    fn none() -> Self {
        Self::None
    }

    fn sse_customer(write: SseCustomerWriteContext) -> Self {
        Self::SseCustomer {
            encryption: write.encryption().clone(),
            write: Some(write),
        }
    }

    fn managed(
        algorithm: ManagedEncryptionAlgorithm,
        write: ManagedEncryptionWriteContext,
    ) -> Self {
        Self::Managed {
            encryption: write.encryption().clone(),
            algorithm,
            write: Some(write),
        }
    }

    pub fn as_ref(&self) -> ActiveWriteEncryptionRef<'_> {
        match self {
            Self::None => ActiveWriteEncryptionRef::None,
            Self::SseCustomer {
                write: Some(sse_customer),
                ..
            } => ActiveWriteEncryptionRef::SseCustomer(sse_customer),
            Self::SseCustomer { write: None, .. } => ActiveWriteEncryptionRef::None,
            Self::Managed {
                algorithm,
                write: Some(write),
                ..
            } => ActiveWriteEncryptionRef::Managed {
                algorithm: *algorithm,
                write,
            },
            Self::Managed { write: None, .. } => ActiveWriteEncryptionRef::None,
        }
    }

    fn is_sse_customer(&self) -> bool {
        matches!(self, Self::SseCustomer { .. })
    }

    fn object_encryption(&self) -> ObjectEncryption {
        match self {
            Self::None => ObjectEncryption::None,
            Self::SseCustomer { encryption, .. } | Self::Managed { encryption, .. } => {
                encryption.clone()
            }
        }
    }

    pub fn encrypt_segment(&self, segment_index: u32, data: &[u8]) -> Result<Vec<u8>, ServerError> {
        match self {
            Self::None => Ok(data.to_vec()),
            Self::SseCustomer {
                write: Some(sse_customer),
                ..
            } => sse_customer.encrypt_segment(segment_index, data),
            Self::Managed {
                write: Some(write), ..
            } => write.encrypt_segment(segment_index, data),
            Self::SseCustomer { write: None, .. } => Err(ServerError::InvalidRequest {
                reason: "SSE-C write context is required for streaming segment encryption"
                    .to_string(),
            }),
            Self::Managed { write: None, .. } => Err(ServerError::InternalError {
                reason: "SSE-S3 write context is required for streaming segment encryption"
                    .to_string(),
            }),
        }
    }

    fn from_stored_and_active(
        encryption: &ObjectEncryption,
        active: ActiveWriteEncryptionRef<'_>,
    ) -> Result<Self, ServerError> {
        match (encryption, active) {
            (ObjectEncryption::None, ActiveWriteEncryptionRef::None) => Ok(Self::None),
            (ObjectEncryption::None, ActiveWriteEncryptionRef::SseCustomer(_))
            | (ObjectEncryption::None, ActiveWriteEncryptionRef::Managed { .. }) => {
                Err(ServerError::InvalidRequest {
                    reason: "write encryption context does not match unencrypted session"
                        .to_string(),
                })
            }
            (
                ObjectEncryption::SseCustomer(state),
                ActiveWriteEncryptionRef::SseCustomer(sse_customer),
            ) => {
                if sse_customer.encryption() != encryption {
                    return Err(ServerError::InvalidRequest {
                        reason: "SSE-C write context does not match session encryption state"
                            .to_string(),
                    });
                }
                let _ = state;
                Ok(Self::sse_customer(sse_customer.clone()))
            }
            (ObjectEncryption::SseCustomer(state), ActiveWriteEncryptionRef::None) => {
                Ok(Self::SseCustomer {
                    encryption: ObjectEncryption::SseCustomer(state.clone()),
                    write: None,
                })
            }
            (ObjectEncryption::SseCustomer(_), ActiveWriteEncryptionRef::Managed { .. }) => {
                Err(ServerError::InvalidRequest {
                    reason: "managed write context may not be used for an SSE-C session"
                        .to_string(),
                })
            }
            (
                ObjectEncryption::SseS3(_),
                ActiveWriteEncryptionRef::Managed { algorithm, write },
            ) => {
                if Some(algorithm) != encryption.managed_encryption_algorithm() {
                    return Err(ServerError::InternalError {
                        reason: "SSE-S3 session is missing managed write encryption context"
                            .to_string(),
                    });
                }
                if write.encryption() != encryption {
                    return Err(ServerError::InvalidRequest {
                        reason: "SSE-S3 write context does not match session encryption state"
                            .to_string(),
                    });
                }
                Ok(Self::managed(algorithm, write.clone()))
            }
            (ObjectEncryption::SseS3(state), ActiveWriteEncryptionRef::None) => Ok(Self::Managed {
                encryption: ObjectEncryption::SseS3(state.clone()),
                algorithm: ManagedEncryptionAlgorithm::Aes256,
                write: None,
            }),
            (ObjectEncryption::SseS3(_), ActiveWriteEncryptionRef::SseCustomer(_)) => {
                Err(ServerError::InvalidRequest {
                    reason: "SSE-C headers may not be used for an SSE-S3 session".to_string(),
                })
            }
        }
    }
}

#[derive(Debug, Clone)]
pub struct ReadChunk {
    data: Arc<SharedPayloadBuffer>,
    start: usize,
    end: usize,
}

impl ReadChunk {
    fn from_vec(data: Vec<u8>) -> Self {
        let len = data.len();
        Self {
            data: Arc::new(SharedPayloadBuffer::from_unpooled(data)),
            start: 0,
            end: len,
        }
    }

    fn from_shared_range(data: Arc<SharedPayloadBuffer>, start: usize, end: usize) -> Self {
        debug_assert!(start <= end);
        debug_assert!(end <= data.len());
        Self { data, start, end }
    }

    pub fn len(&self) -> usize {
        self.end - self.start
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

impl AsRef<[u8]> for ReadChunk {
    fn as_ref(&self) -> &[u8] {
        &self.data.buf[self.start..self.end]
    }
}

impl std::ops::Deref for ReadChunk {
    type Target = [u8];

    fn deref(&self) -> &Self::Target {
        self.as_ref()
    }
}

#[derive(Debug)]
struct PayloadBufferPool {
    default_capacity: usize,
    max_cached: usize,
    cached: Mutex<Vec<Vec<u8>>>,
    #[cfg(test)]
    allocations: std::sync::atomic::AtomicUsize,
}

struct PooledPayloadBuffer {
    pool: Arc<PayloadBufferPool>,
    buf: Option<Vec<u8>>,
}

#[derive(Debug)]
struct SharedPayloadBuffer {
    pool: Option<Arc<PayloadBufferPool>>,
    buf: Vec<u8>,
}

impl PayloadBufferPool {
    fn new(ec_config: EcConfig) -> Arc<Self> {
        let default_capacity = segment_payload_buffer_capacity(ec_config);
        let max_cached = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(4)
            .max(1);
        Arc::new(Self {
            default_capacity,
            max_cached,
            cached: Mutex::new(Vec::new()),
            #[cfg(test)]
            allocations: std::sync::atomic::AtomicUsize::new(0),
        })
    }

    fn checkout(self: &Arc<Self>, required_capacity: usize) -> PooledPayloadBuffer {
        let min_capacity = required_capacity.max(self.default_capacity);
        let mut cached = lock_mutex_unpoisoned(&self.cached);
        let maybe_idx = cached
            .iter()
            .rposition(|buf| buf.capacity() >= min_capacity);
        let mut buf = maybe_idx.map_or_else(
            || {
                #[cfg(test)]
                self.allocations.fetch_add(1, Ordering::Relaxed);
                Vec::with_capacity(min_capacity)
            },
            |idx| cached.swap_remove(idx),
        );
        drop(cached);
        buf.clear();
        PooledPayloadBuffer {
            pool: Arc::clone(self),
            buf: Some(buf),
        }
    }

    fn recycle(&self, mut buf: Vec<u8>) {
        if buf.capacity() < self.default_capacity {
            return;
        }
        buf.clear();
        let mut cached = lock_mutex_unpoisoned(&self.cached);
        if cached.len() < self.max_cached {
            cached.push(buf);
        }
    }

    #[cfg(test)]
    fn allocation_count(&self) -> usize {
        self.allocations.load(Ordering::Relaxed)
    }
}

impl PooledPayloadBuffer {
    fn resize_zeroed(&mut self, len: usize) {
        self.buf.as_mut().unwrap().resize(len, 0);
    }

    fn truncate(&mut self, len: usize) {
        self.buf.as_mut().unwrap().truncate(len);
    }

    fn into_shared(mut self) -> Arc<SharedPayloadBuffer> {
        Arc::new(SharedPayloadBuffer {
            pool: Some(Arc::clone(&self.pool)),
            buf: self.buf.take().unwrap(),
        })
    }
}

impl std::ops::Deref for PooledPayloadBuffer {
    type Target = Vec<u8>;

    fn deref(&self) -> &Self::Target {
        self.buf.as_ref().unwrap()
    }
}

impl std::ops::DerefMut for PooledPayloadBuffer {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.buf.as_mut().unwrap()
    }
}

impl Drop for PooledPayloadBuffer {
    fn drop(&mut self) {
        let Some(buf) = self.buf.take() else {
            return;
        };
        self.pool.recycle(buf);
    }
}

impl SharedPayloadBuffer {
    fn from_unpooled(buf: Vec<u8>) -> Self {
        Self { pool: None, buf }
    }

    fn len(&self) -> usize {
        self.buf.len()
    }
}

impl std::ops::Deref for SharedPayloadBuffer {
    type Target = [u8];

    fn deref(&self) -> &Self::Target {
        &self.buf
    }
}

impl Drop for SharedPayloadBuffer {
    fn drop(&mut self) {
        let Some(pool) = self.pool.take() else {
            return;
        };
        pool.recycle(std::mem::take(&mut self.buf));
    }
}

struct EncodeScratchPool {
    scratch_len: usize,
    max_cached: usize,
    cached: Mutex<Vec<Vec<u8>>>,
    #[cfg(test)]
    allocations: std::sync::atomic::AtomicUsize,
}

struct EncodeScratch<'a> {
    pool: &'a EncodeScratchPool,
    buf: Option<Vec<u8>>,
}

impl EncodeScratchPool {
    fn new(ec_config: EcConfig) -> Self {
        let scratch_len = encode_parity_scratch_len(ec_config);
        let max_cached = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(4)
            .max(1);
        Self {
            scratch_len,
            max_cached,
            cached: Mutex::new(Vec::new()),
            #[cfg(test)]
            allocations: std::sync::atomic::AtomicUsize::new(0),
        }
    }

    fn checkout(&self) -> EncodeScratch<'_> {
        let buf = lock_mutex_unpoisoned(&self.cached)
            .pop()
            .unwrap_or_else(|| {
                #[cfg(test)]
                self.allocations.fetch_add(1, Ordering::Relaxed);
                vec![0u8; self.scratch_len]
            });
        EncodeScratch {
            pool: self,
            buf: Some(buf),
        }
    }

    #[cfg(test)]
    fn allocation_count(&self) -> usize {
        self.allocations.load(Ordering::Relaxed)
    }
}

impl EncodeScratch<'_> {
    fn as_mut_slice(&mut self, len: usize) -> &mut [u8] {
        debug_assert!(len <= self.pool.scratch_len);
        &mut self.buf.as_mut().unwrap()[..len]
    }

    fn as_slice(&self, len: usize) -> &[u8] {
        debug_assert!(len <= self.pool.scratch_len);
        &self.buf.as_ref().unwrap()[..len]
    }
}

impl Drop for EncodeScratch<'_> {
    fn drop(&mut self) {
        let Some(buf) = self.buf.take() else {
            return;
        };
        let mut cached = lock_mutex_unpoisoned(&self.pool.cached);
        if cached.len() < self.pool.max_cached {
            cached.push(buf);
        }
    }
}

fn encode_parity_scratch_len(ec_config: EcConfig) -> usize {
    let k = ec_config.data_shards as usize;
    let m = ec_config.parity_shards as usize;
    let padded = max_stored_segment_size().div_ceil(k) * k;
    let shard_size = padded / k;
    shard_size.saturating_mul(m)
}

fn segment_payload_buffer_capacity(ec_config: EcConfig) -> usize {
    let k = ec_config.data_shards as usize;
    max_stored_segment_size().div_ceil(k) * k
}

fn max_stored_segment_size() -> usize {
    // Encrypted objects store an authentication tag alongside the largest
    // logical segment.
    INTERNAL_SEGMENT_SIZE.saturating_add(SSE_C_SEGMENT_TAG_LEN)
}

#[derive(Clone)]
struct ReadRuntime {
    storage_node: Arc<SharedStorageNode>,
    ec_codec: Arc<ErasureCodec>,
    ec_config: EcConfig,
    pg_topology: PgTopology,
    payload_buffer_pool: Arc<PayloadBufferPool>,
    sse_c_validator: Option<SseCustomerValidatorConfig>,
    managed_key_provider: Option<StaticManagedKeyProvider>,
}

#[derive(Debug, Clone)]
struct SegmentPayloadRecord {
    segment_index: u32,
    size: u64,
    segment_crc64: Option<u64>,
    segment_okh: [u8; 16],
    segment_vid: GenerationId,
    shard_pg_id: u32,
    ec_k: u8,
    ec_m: u8,
    encryption: ObjectEncryption,
}

impl SegmentPayloadRecord {
    fn stored_size(&self) -> usize {
        self.size as usize + self.encryption.segment_ciphertext_extra_len()
    }
}

#[cfg_attr(not(feature = "deep-tracing"), allow(dead_code))]
#[derive(Debug, Clone)]
struct SegmentSliceRecord {
    payload: SegmentPayloadRecord,
    segment_index: usize,
    segment_object_offset_start: usize,
    segment_object_offset_end_exclusive: usize,
    start_offset: usize,
    end_offset: usize,
    part_number: Option<u32>,
    part_order: Option<usize>,
    part_object_offset_start: Option<usize>,
    part_object_offset_end_exclusive: Option<usize>,
}

struct WrittenShard {
    key: ShardKey,
    ack: storage::WriteAck,
}

#[derive(Debug, Clone)]
struct MultipartPartReadLayout {
    part_number: u32,
    part_order: usize,
    object_offset_start: usize,
    object_offset_end_exclusive: usize,
}

struct SegmentListReader {
    runtime: ReadRuntime,
    bucket: String,
    key: String,
    segments: Vec<SegmentSliceRecord>,
    next_segment_index: usize,
    loaded_segment: Option<(Arc<SharedPayloadBuffer>, usize, usize)>,
    sse_customer_request: Option<SseCustomerRequest>,
}

#[cfg_attr(not(feature = "deep-tracing"), allow(dead_code))]
#[derive(Debug, Clone)]
struct SnapshottedMultipartPartRange {
    layout: MultipartPartReadLayout,
    segments: Vec<SegmentSliceRecord>,
}

struct MultipartReader {
    runtime: ReadRuntime,
    bucket: String,
    key: String,
    parts: Vec<SnapshottedMultipartPartRange>,
    next_part_index: usize,
    current_part: Option<SegmentListReader>,
    sse_customer_request: Option<SseCustomerRequest>,
}

struct ReadObjectContext<'a> {
    runtime: ReadRuntime,
    bucket: &'a BucketName,
    key: &'a ObjectKey,
    generation_id: GenerationId,
    sse_customer_request: Option<SseCustomerRequest>,
}

// Boxing the segment reader would add heap traffic on the normal read path.
#[allow(clippy::large_enum_variant)]
enum ReadHandleInner {
    Segments(SegmentListReader),
    Multipart(Box<MultipartReader>),
    TestBuffered(Option<Vec<u8>>),
}

struct PayloadLease {
    runtime: ReadRuntime,
    bucket: BucketName,
    key: ObjectKey,
    generation_id: GenerationId,
}

impl Drop for PayloadLease {
    fn drop(&mut self) {
        if self.storage_node().release_object_payload_lease(
            &self.bucket,
            &self.key,
            self.generation_id,
        ) == 0
        {
            match self.runtime.object_payload_reclaim_exists_for(
                &self.bucket,
                &self.key,
                self.generation_id,
            ) {
                Ok(true) | Err(_) => self.runtime.enqueue_object_payload_reclaim_for(
                    &self.bucket,
                    &self.key,
                    self.generation_id,
                ),
                Ok(false) => {}
            }
        }
    }
}

impl PayloadLease {
    fn storage_node(&self) -> &SharedStorageNode {
        &self.runtime.storage_node
    }
}

/// Core-owned streaming object body.
pub struct ReadHandle {
    bucket: String,
    key: String,
    inner: ReadHandleInner,
    lease: Option<PayloadLease>,
    trace: Option<observability::TraceContext>,
    expected_size: usize,
    bytes_emitted: usize,
    expected_crc64: Option<u64>,
    crc64: checksum::crc64::Hasher,
}

impl std::fmt::Debug for ReadHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ReadHandle")
            .field("bucket", &self.bucket)
            .field("key", &self.key)
            .field("has_lease", &self.lease.is_some())
            .field("expected_size", &self.expected_size)
            .field("bytes_emitted", &self.bytes_emitted)
            .field("expected_crc64", &self.expected_crc64)
            .finish_non_exhaustive()
    }
}

impl ReadHandle {
    fn segment_slices_for_range(
        segments: Vec<SegmentPayloadRecord>,
        start: usize,
        end: usize,
        object_offset_base: usize,
        part_layout: Option<&MultipartPartReadLayout>,
    ) -> Vec<SegmentSliceRecord> {
        let mut slices = Vec::new();
        let mut offset = 0usize;

        for (segment_index, payload) in segments.into_iter().enumerate() {
            let segment_end = offset + payload.size as usize;
            if offset > end {
                break;
            }
            if payload.size != 0 && segment_end > start {
                let start_offset = start.saturating_sub(offset);
                let end_offset = (end + 1).saturating_sub(offset).min(payload.size as usize);
                slices.push(SegmentSliceRecord {
                    payload,
                    segment_index,
                    segment_object_offset_start: object_offset_base + offset,
                    segment_object_offset_end_exclusive: object_offset_base + segment_end,
                    start_offset,
                    end_offset,
                    part_number: part_layout.map(|layout| layout.part_number),
                    part_order: part_layout.map(|layout| layout.part_order),
                    part_object_offset_start: part_layout.map(|layout| layout.object_offset_start),
                    part_object_offset_end_exclusive: part_layout
                        .map(|layout| layout.object_offset_end_exclusive),
                });
            }
            offset = segment_end;
        }

        slices
    }

    fn multipart_ranges_for_range(
        parts: Vec<SnapshottedMultipartPart>,
        start: usize,
        end: usize,
    ) -> Vec<SnapshottedMultipartPartRange> {
        let mut ranges = Vec::new();

        for (part_order, part) in parts.into_iter().enumerate() {
            let part_start = part.object_offset_start;
            let part_end = part_start + part.record.size as usize;
            if part_start > end {
                break;
            }
            if part.record.size != 0 && part_end > start {
                let start_offset = start.saturating_sub(part_start);
                let end_offset = (end + 1)
                    .saturating_sub(part_start)
                    .min(part.record.size as usize);
                let layout = MultipartPartReadLayout {
                    part_number: part.record.part_number,
                    part_order,
                    object_offset_start: part_start,
                    object_offset_end_exclusive: part_end,
                };
                ranges.push(SnapshottedMultipartPartRange {
                    layout: layout.clone(),
                    segments: Self::segment_slices_for_range(
                        part.segments,
                        start_offset,
                        end_offset - 1,
                        part_start,
                        Some(&layout),
                    ),
                });
            }
        }

        ranges
    }

    fn from_segments(
        ctx: ReadObjectContext<'_>,
        segments: Vec<SegmentPayloadRecord>,
        expected_size: usize,
        expected_crc64: Option<u64>,
    ) -> Self {
        let ReadObjectContext {
            runtime,
            bucket,
            key,
            generation_id,
            sse_customer_request,
        } = ctx;
        let bucket_owned = bucket.as_str().to_string();
        let key_owned = key.as_str().to_string();
        Self {
            bucket: bucket_owned.clone(),
            key: key_owned.clone(),
            lease: Some(runtime.acquire_object_payload_lease_for(bucket, key, generation_id)),
            trace: observability::current_context(),
            expected_size,
            bytes_emitted: 0,
            expected_crc64,
            crc64: checksum::crc64::Hasher::new(),
            inner: ReadHandleInner::Segments(SegmentListReader {
                runtime,
                bucket: bucket_owned,
                key: key_owned,
                segments: Self::segment_slices_for_range(
                    segments,
                    0,
                    expected_size.saturating_sub(1),
                    0,
                    None,
                ),
                next_segment_index: 0,
                loaded_segment: None,
                sse_customer_request,
            }),
        }
    }

    fn from_segments_range(
        ctx: ReadObjectContext<'_>,
        segments: Vec<SegmentPayloadRecord>,
        start: usize,
        end: usize,
    ) -> Self {
        let ReadObjectContext {
            runtime,
            bucket,
            key,
            generation_id,
            sse_customer_request,
        } = ctx;
        let expected_size = end - start + 1;
        let bucket_owned = bucket.as_str().to_string();
        let key_owned = key.as_str().to_string();
        Self {
            bucket: bucket_owned.clone(),
            key: key_owned.clone(),
            lease: Some(runtime.acquire_object_payload_lease_for(bucket, key, generation_id)),
            trace: observability::current_context(),
            expected_size,
            bytes_emitted: 0,
            expected_crc64: None,
            crc64: checksum::crc64::Hasher::new(),
            inner: ReadHandleInner::Segments(SegmentListReader {
                runtime,
                bucket: bucket_owned,
                key: key_owned,
                segments: Self::segment_slices_for_range(segments, start, end, 0, None),
                next_segment_index: 0,
                loaded_segment: None,
                sse_customer_request,
            }),
        }
    }

    fn from_multipart(
        runtime: ReadRuntime,
        bucket: &BucketName,
        key: &ObjectKey,
        generation_id: GenerationId,
        parts: Vec<SnapshottedMultipartPart>,
        expected_size: usize,
        sse_customer_request: Option<SseCustomerRequest>,
    ) -> Self {
        Self {
            bucket: bucket.as_str().to_string(),
            key: key.as_str().to_string(),
            lease: Some(runtime.acquire_object_payload_lease_for(bucket, key, generation_id)),
            trace: observability::current_context(),
            expected_size,
            bytes_emitted: 0,
            expected_crc64: None,
            crc64: checksum::crc64::Hasher::new(),
            inner: ReadHandleInner::Multipart(Box::new(MultipartReader {
                runtime,
                bucket: bucket.as_str().to_string(),
                key: key.as_str().to_string(),
                parts: Self::multipart_ranges_for_range(parts, 0, expected_size.saturating_sub(1)),
                next_part_index: 0,
                current_part: None,
                sse_customer_request,
            })),
        }
    }

    fn from_multipart_range(
        runtime: ReadRuntime,
        bucket: &BucketName,
        key: &ObjectKey,
        generation_id: GenerationId,
        parts: Vec<SnapshottedMultipartPart>,
        range: (usize, usize),
        sse_customer_request: Option<SseCustomerRequest>,
    ) -> Self {
        let (start, end) = range;
        let expected_size = end - start + 1;
        Self {
            bucket: bucket.as_str().to_string(),
            key: key.as_str().to_string(),
            lease: Some(runtime.acquire_object_payload_lease_for(bucket, key, generation_id)),
            trace: observability::current_context(),
            expected_size,
            bytes_emitted: 0,
            expected_crc64: None,
            crc64: checksum::crc64::Hasher::new(),
            inner: ReadHandleInner::Multipart(Box::new(MultipartReader {
                runtime,
                bucket: bucket.as_str().to_string(),
                key: key.as_str().to_string(),
                parts: Self::multipart_ranges_for_range(parts, start, end),
                next_part_index: 0,
                current_part: None,
                sse_customer_request,
            })),
        }
    }

    pub fn from_buffered_bytes(data: Vec<u8>) -> Self {
        let len = data.len();
        Self {
            bucket: "<buffered>".to_string(),
            key: "<buffered>".to_string(),
            inner: ReadHandleInner::TestBuffered(Some(data)),
            lease: None,
            trace: observability::current_context(),
            expected_size: len,
            bytes_emitted: 0,
            expected_crc64: None,
            crc64: checksum::crc64::Hasher::new(),
        }
    }

    pub fn next_chunk(&mut self, target_size: usize) -> Result<Option<ReadChunk>, ServerError> {
        let _trace = self.trace.clone().map(observability::AttachedTrace::new);
        observability::trace_scope!(
            TRACE_TARGET,
            "ReadHandle::next_chunk",
            "bucket={:?} key={:?} target_size={}",
            self.bucket,
            self.key,
            target_size
        );
        if target_size == 0 {
            return Ok(Some(ReadChunk::from_vec(Vec::new())));
        }

        let next = match &mut self.inner {
            ReadHandleInner::Segments(reader) => reader.next_chunk(target_size),
            ReadHandleInner::Multipart(reader) => reader.next_chunk(target_size),
            ReadHandleInner::TestBuffered(data) => Ok(data.take().map(ReadChunk::from_vec)),
        }?;

        if let Some(chunk) = next {
            self.bytes_emitted += chunk.len();
            self.crc64.update(chunk.as_ref());
            Ok(Some(chunk))
        } else {
            if self.bytes_emitted != self.expected_size {
                return Err(ServerError::IntegrityError {
                    bucket: self.bucket.clone(),
                    key: self.key.clone(),
                    expected: self.expected_size as u64,
                    actual: self.bytes_emitted as u64,
                });
            }
            if let Some(expected_crc64) = self.expected_crc64 {
                let actual_crc64 = self.crc64.finalize();
                if actual_crc64 != expected_crc64 {
                    return Err(ServerError::IntegrityError {
                        bucket: self.bucket.clone(),
                        key: self.key.clone(),
                        expected: expected_crc64,
                        actual: actual_crc64,
                    });
                }
            }
            Ok(None)
        }
    }
}

fn segment_payloads_from_object_segments(
    segments: Vec<ObjectSegmentRecord>,
    encryption: ObjectEncryption,
) -> Vec<SegmentPayloadRecord> {
    segments
        .into_iter()
        .map(|segment| SegmentPayloadRecord {
            segment_index: segment.segment_index,
            size: segment.size,
            segment_crc64: segment.segment_crc64,
            segment_okh: segment.segment_okh,
            segment_vid: segment.segment_vid,
            shard_pg_id: segment.shard_pg_id,
            ec_k: segment.ec_k,
            ec_m: segment.ec_m,
            encryption: encryption.clone(),
        })
        .collect()
}

