struct ReclaimSweeper {
    storage_node: Arc<SharedStorageNode>,
    stop: Arc<AtomicBool>,
    handle: Option<JoinHandle<()>>,
}

struct LifecycleSweeper {
    stop: Arc<AtomicBool>,
    handle: Mutex<Option<JoinHandle<()>>>,
}

