    // ── Object operations ─────────────────────────────────────────────

    fn prepare_put_commit_locked(
        &self,
        meta_pg: &storage::PgStore,
        bucket_info: &BucketSummary,
        req: &PutCommitRequest<'_>,
    ) -> Result<PreparedPutCommit, ServerError> {
        self.ensure_write_encryption_supported(&req.write_encryption.object_encryption())?;
        let metadata_blob = SerializedMetadataBlob::from(req.metadata_blob.serialize()?);
        let (system_metadata_blob, encryption) =
            Self::prepare_stored_system_metadata(req.system_metadata, req.write_encryption)?;

        if !req.cond.is_empty() {
            let existing_etag =
                match storage::PgMetadataStore::get_object_meta(meta_pg, req.bucket, req.key) {
                    Ok(stored) => stored.as_live().map(|record| record.etag.format()),
                    Err(storage::MetadataError::ObjectNotFound) => None,
                    Err(e) => return Err(ServerError::Metadata(e)),
                };
            if matches!(req.cond, WriteCondition::IfMatch(_)) && existing_etag.is_none() {
                return Err(ServerError::ObjectNotFound {
                    bucket: req.bucket.to_string(),
                    key: req.key.to_string(),
                });
            }
            check_write_conditions(req.cond, existing_etag.as_deref())?;
        }

        let version_id = if bucket_info.versioning == BucketVersioningState::Enabled {
            storage::PgMetadataStore::next_version_id(meta_pg, req.bucket, req.key)?
        } else {
            VersionId::Null
        };
        let generation_id =
            storage::PgMetadataStore::next_generation_id(meta_pg, req.bucket, req.key)?;
        let stale_payload = if version_id.is_null() {
            Self::snapshot_overwritten_null_version_payload(meta_pg, req.bucket, req.key)?
        } else {
            None
        };

        Ok(PreparedPutCommit {
            version_id,
            generation_id,
            tags: req.tags.map(SerializedTagSet::from),
            metadata_blob,
            system_metadata_blob,
            encryption,
            stale_payload,
        })
    }

    fn object_system_metadata_with_default_checksum(
        system_metadata: &SystemMetadata,
        write_encryption: &ActiveWriteEncryption,
        crc64: u64,
    ) -> SystemMetadata {
        let mut normalized_system_metadata = system_metadata.clone();
        if let Some(checksum) = normalized_system_metadata.take_checksum() {
            normalized_system_metadata.set_checksum(
                checksum.algorithm(),
                checksum.checksum_type().or(Some(ChecksumType::FullObject)),
                checksum.value(),
            );
        }
        let can_store_checksum = matches!(
            write_encryption,
            ActiveWriteEncryption::None
                | ActiveWriteEncryption::SseCustomer { write: Some(_), .. }
                | ActiveWriteEncryption::Managed { write: Some(_), .. }
        );
        if normalized_system_metadata.checksum().is_some() || !can_store_checksum {
            return normalized_system_metadata;
        }
        use base64::Engine;
        let mut system_metadata = normalized_system_metadata;
        let checksum = base64::engine::general_purpose::STANDARD.encode(crc64.to_be_bytes());
        system_metadata.set_checksum(
            ChecksumAlgorithm::Crc64nvme,
            Some(ChecksumType::FullObject),
            checksum,
        );
        system_metadata
    }

    fn finalize_put_commit_metadata_locked(
        meta_pg: &storage::PgStore,
        bucket: &BucketName,
        key: &ObjectKey,
        version_id: VersionId,
        stale_payload: Option<&StaleObjectPayload>,
    ) -> Result<(), ServerError> {
        if let Some(payload) = stale_payload {
            match payload {
                StaleObjectPayload::Segments {
                    generation_id,
                    segments,
                } => {
                    Self::enqueue_object_segments_reclaim(
                        meta_pg,
                        bucket,
                        key,
                        *generation_id,
                        segments,
                    )?;
                }
                StaleObjectPayload::Multipart { .. } => {
                    Self::delete_stale_object_payload_metadata(
                        meta_pg, bucket, key, version_id, payload,
                    )?;
                }
            }
        }

        Ok(())
    }

    pub fn prepare_sse_customer_write_context(
        &self,
        sse_customer: Option<&SseCustomerRequest>,
    ) -> Result<Option<crate::sse::SseCustomerWriteContext>, ServerError> {
        match sse_customer {
            None => Ok(None),
            Some(request) => {
                let validator =
                    self.sse_c_validator
                        .as_ref()
                        .ok_or(ServerError::NotImplemented {
                            feature: "SSE-C requires ARGMIN_SSE_C_VALIDATOR_KEY".to_string(),
                        })?;
                Ok(Some(prepare_sse_customer_write(validator, request)?))
            }
        }
    }

    pub fn prepare_managed_write_context(
        &self,
    ) -> Result<ManagedEncryptionWriteContext, ServerError> {
        let provider = self
            .managed_key_provider
            .as_ref()
            .ok_or(ServerError::NotImplemented {
                feature: "SSE-S3 requires managed key provider configuration".to_string(),
            })?;
        prepare_managed_encryption_write(provider)
    }

    fn resolve_write_encryption(
        &self,
        bucket: &BucketSummary,
        request_encryption: WriteEncryptionRequest<'_>,
    ) -> Result<ActiveWriteEncryption, ServerError> {
        if let Some(sse_customer_request) = request_encryption.sse_customer_request() {
            let sse_customer =
                self.prepare_sse_customer_write_context(Some(sse_customer_request))?;
            return Ok(ActiveWriteEncryption::sse_customer(
                sse_customer.expect("SSE-C request should produce write context"),
            ));
        }

        if request_encryption.explicit_managed_encryption().is_some()
            || bucket.encryption.default_encryption == ManagedEncryptionAlgorithm::Aes256
        {
            let managed_write = self.prepare_managed_write_context()?;
            return Ok(ActiveWriteEncryption::managed(
                ManagedEncryptionAlgorithm::Aes256,
                managed_write,
            ));
        }

        Ok(ActiveWriteEncryption::none())
    }

    fn resume_write_encryption(
        &self,
        encryption: &ObjectEncryption,
        sse_customer: Option<&SseCustomerRequest>,
        segment_scope: SseCustomerSegmentScope,
        sse_customer_headers_required: bool,
    ) -> Result<ActiveWriteEncryption, ServerError> {
        match encryption {
            ObjectEncryption::None => {
                let sse_customer = self.prepare_existing_sse_customer_write_context(
                    encryption,
                    sse_customer,
                    segment_scope,
                    sse_customer_headers_required,
                )?;
                Ok(match sse_customer {
                    Some(sse_customer) => ActiveWriteEncryption::sse_customer(sse_customer),
                    None => ActiveWriteEncryption::None,
                })
            }
            ObjectEncryption::SseCustomer(state) => {
                let sse_customer = self.prepare_existing_sse_customer_write_context(
                    encryption,
                    sse_customer,
                    segment_scope,
                    sse_customer_headers_required,
                )?;
                Ok(match sse_customer {
                    Some(sse_customer) => ActiveWriteEncryption::sse_customer(sse_customer),
                    None => ActiveWriteEncryption::SseCustomer {
                        encryption: ObjectEncryption::SseCustomer(state.clone()),
                        write: None,
                    },
                })
            }
            ObjectEncryption::SseS3(state) => {
                if sse_customer.is_some() {
                    return Err(ServerError::InvalidRequest {
                        reason: "SSE-C headers may not be used for a non-SSE-C upload".to_string(),
                    });
                }
                let provider =
                    self.managed_key_provider
                        .as_ref()
                        .ok_or(ServerError::InternalError {
                            reason: "SSE-S3 key provider is not configured".to_string(),
                        })?;
                let managed_write =
                    resume_managed_encryption_write(provider, state, segment_scope)?;
                Ok(ActiveWriteEncryption::managed(
                    ManagedEncryptionAlgorithm::Aes256,
                    managed_write,
                ))
            }
        }
    }

    pub fn load_stream_put_write_encryption(
        &self,
        bucket: &BucketName,
        key: &ObjectKey,
        session_id: &SessionId,
        sse_customer: Option<&SseCustomerRequest>,
    ) -> Result<ActiveWriteEncryption, ServerError> {
        let meta_pg = self
            .storage_node
            .get_pg(self.object_pg_id_for(bucket, key))?;
        let session = meta_pg.get_stream_upload(session_id)?;
        if session.bucket != *bucket || session.key != *key {
            return Err(ServerError::InvalidRequest {
                reason: "session bucket/key mismatch".to_string(),
            });
        }
        self.resume_write_encryption(
            &session.encryption,
            sse_customer,
            SseCustomerSegmentScope::object(),
            false,
        )
    }

    pub fn load_stream_part_write_encryption(
        &self,
        bucket: &BucketName,
        key: &ObjectKey,
        session_id: &SessionId,
        part_number: u32,
        sse_customer: Option<&SseCustomerRequest>,
    ) -> Result<ActiveWriteEncryption, ServerError> {
        let meta_pg = self
            .storage_node
            .get_pg(self.object_pg_id_for(bucket, key))?;
        let session = meta_pg.get_stream_upload(session_id)?;
        if session.bucket != *bucket || session.key != *key {
            return Err(ServerError::InvalidRequest {
                reason: "session bucket/key mismatch".to_string(),
            });
        }
        self.resume_write_encryption(
            &session.encryption,
            sse_customer,
            SseCustomerSegmentScope::multipart_part(part_number)?,
            false,
        )
    }

    #[cfg(test)]
    fn load_stream_session_write_encryption(
        &self,
        bucket: &BucketName,
        key: &ObjectKey,
        session_id: &SessionId,
        sse_customer: Option<&SseCustomerRequest>,
    ) -> Result<ActiveWriteEncryption, ServerError> {
        let meta_pg = self
            .storage_node
            .get_pg(self.object_pg_id_for(bucket, key))?;
        let target = meta_pg.get_stream_upload(session_id)?.target;
        drop(meta_pg);
        match target {
            StreamUploadTarget::PutObject => {
                self.load_stream_put_write_encryption(bucket, key, session_id, sse_customer)
            }
            StreamUploadTarget::UploadPart { part_number, .. } => self
                .load_stream_part_write_encryption(
                    bucket,
                    key,
                    session_id,
                    part_number,
                    sse_customer,
                ),
        }
    }

