    #[test]
    fn delete_objects_batch() {
        let tmp = test_util::tempdir();
        let coord = setup_coordinator(tmp.path());

        coord
            .create_bucket_for_owner("default-owner", "bucket", false)
            .unwrap();
        test_helpers::put_object(
            &coord,
            &PutObjectRequest {
                encryption: WriteEncryptionRequest::none(),
                policy_context: PutObjectPolicyContext::default(),
                object_lock: ObjectLockState::default(),
                object: object_request_with_expected_owner(
                    "bucket",
                    "key1",
                    test_requester(),
                    None,
                ),
                data: b"data1",
                metadata: &MetadataBlob::new(),
                system_metadata: &SystemMetadata::EMPTY,
                tags: None,
                cond: NO_WRITE,

                acl: NO_PUT_OBJECT_ACL.into(),
            },
        )
        .unwrap();
        test_helpers::put_object(
            &coord,
            &PutObjectRequest {
                encryption: WriteEncryptionRequest::none(),
                policy_context: PutObjectPolicyContext::default(),
                object_lock: ObjectLockState::default(),
                object: object_request_with_expected_owner(
                    "bucket",
                    "key2",
                    test_requester(),
                    None,
                ),
                data: b"data2",
                metadata: &MetadataBlob::new(),
                system_metadata: &SystemMetadata::EMPTY,
                tags: None,
                cond: NO_WRITE,

                acl: NO_PUT_OBJECT_ACL.into(),
            },
        )
        .unwrap();

        let entries = vec![
            DeleteEntry {
                key: trusted_object_key("key1"),
                version_id: None,
                cond: DeleteCondition::None,
            },
            DeleteEntry {
                key: trusted_object_key("key2"),
                version_id: None,
                cond: DeleteCondition::None,
            },
            // key3 doesn't exist — should still succeed (idempotent)
            DeleteEntry {
                key: trusted_object_key("key3"),
                version_id: None,
                cond: DeleteCondition::None,
            },
        ];

        let result = coord
            .delete_objects(&DeleteObjectsRequest {
                bucket: bucket_request_with_expected_owner("bucket", test_requester(), None),
                entries: &entries,
                bypass_governance: false,
            })
            .unwrap();
        assert_eq!(result.deleted.len(), 3);
        assert!(result.errors.is_empty());

        // Verify objects are actually gone
        assert!(coord
            .get_object(&GetObjectRequest {
                sse_customer: None,
                object: object_version_request_with_expected_owner(
                    "bucket",
                    "key1",
                    None,
                    test_requester(),
                    None
                ),
                cond: NO_READ,
            })
            .is_err());
        assert!(coord
            .get_object(&GetObjectRequest {
                sse_customer: None,
                object: object_version_request_with_expected_owner(
                    "bucket",
                    "key2",
                    None,
                    test_requester(),
                    None
                ),
                cond: NO_READ,
            })
            .is_err());
    }

