    #[test]
    fn delete_bucket_drains_unqueued_payload_reclaim() {
        let tmp = test_util::tempdir();
        let coord = setup_coordinator(tmp.path());
        coord
            .create_bucket_for_owner("default-owner", "bucket", false)
            .unwrap();

        let generation_id = GenerationId::new(1).unwrap();
        let meta_pg_id = coord.object_pg_id("bucket", "ghost");
        {
            let pg = coord.storage_node.get_pg(meta_pg_id).unwrap();
            pg.put_simple_payload_reclaim(&SimplePayloadReclaimRecord {
                bucket: trusted_bucket_name("bucket"),
                key: trusted_object_key("ghost"),
                generation_id,
                ec: EcShape { k: 4, m: 2 },
                created_at: 1,
            })
            .unwrap();
        }

        delete_bucket_test(&coord, "bucket").unwrap();
        assert!(matches!(
            coord.unchecked_active_bucket_summary("bucket"),
            Err(ServerError::BucketNotFound { .. })
        ));

        wait_until_bucket_gone(&coord, "bucket");

        let pg = coord.storage_node.get_pg(meta_pg_id).unwrap();
        assert!(pg
            .get_simple_payload_reclaim(
                &trusted_bucket_name("bucket"),
                &trusted_object_key("ghost"),
                generation_id
            )
            .unwrap()
            .is_none());
    }

    #[test]
    fn delete_bucket_returns_before_payload_lease_and_reclaim_complete() {
        let tmp = test_util::tempdir();
        let pg_ids: Vec<u32> = (0..4).collect();
        let storage_node = Arc::new(SharedStorageNode::open(tmp.path(), &pg_ids).unwrap());
        let admin = setup_coordinator_with_shared_storage(Arc::clone(&storage_node));
        let deleter = setup_coordinator_with_shared_storage(Arc::clone(&storage_node));
        admin
            .create_bucket_for_owner("default-owner", "bucket", false)
            .unwrap();

        let metadata = MetadataBlob::new();
        test_helpers::put_object(
            &admin,
            &PutObjectRequest {
                encryption: WriteEncryptionRequest::none(),
                policy_context: PutObjectPolicyContext::default(),
                object_lock: ObjectLockState::default(),
                object: object_request_with_expected_owner("bucket", "key", test_requester(), None),
                data: b"hello world",
                metadata: &metadata,
                system_metadata: &SystemMetadata::EMPTY,
                tags: None,
                cond: NO_WRITE,

                acl: NO_PUT_OBJECT_ACL.into(),
            },
        )
        .unwrap();

        let held_read = admin
            .get_object(&GetObjectRequest {
                sse_customer: None,
                object: object_version_request_with_expected_owner(
                    "bucket",
                    "key",
                    None,
                    test_requester(),
                    None,
                ),
                cond: NO_READ,
            })
            .unwrap();

        let generation_id = {
            let meta_pg_id = admin.object_pg_id("bucket", "key");
            let pg = admin.storage_node.get_pg(meta_pg_id).unwrap();
            match pg
                .get_object_meta(&trusted_bucket_name("bucket"), &trusted_object_key("key"))
                .unwrap()
            {
                StoredObject::Live(record) => record.generation_id,
                other @ StoredObject::DeleteMarker(_) => {
                    panic!("expected live object, got {other:?}")
                }
            }
        };

        admin
            .delete_object(&delete_object_request(
                "bucket",
                "key",
                None,
                test_requester(),
                false,
                NO_DELETE,
            ))
            .unwrap();

        let meta_pg_id = admin.object_pg_id("bucket", "key");
        {
            let pg = admin.storage_node.get_pg(meta_pg_id).unwrap();
            assert!(pg
                .get_object_segments_reclaim(
                    &trusted_bucket_name("bucket"),
                    &trusted_object_key("key"),
                    generation_id
                )
                .unwrap()
                .is_some());
        }

        delete_bucket_test(&deleter, "bucket").unwrap();
        assert!(matches!(
            deleter.unchecked_active_bucket_summary("bucket"),
            Err(ServerError::BucketNotFound { .. })
        ));
        assert!(matches!(
            deleter.create_bucket_for_owner("default-owner", "bucket", false),
            Err(ServerError::BucketAlreadyExists)
        ));

        {
            let pg = admin.storage_node.get_pg(meta_pg_id).unwrap();
            assert!(pg
                .get_object_segments_reclaim(
                    &trusted_bucket_name("bucket"),
                    &trusted_object_key("key"),
                    generation_id
                )
                .unwrap()
                .is_some());
        }

        drop(held_read);
        wait_until_bucket_gone(&deleter, "bucket");
    }

