    #[test]
    fn abort_multipart_upload_idempotent() {
        let tmp = test_util::tempdir();
        let coord = setup_coordinator(tmp.path());
        coord
            .create_bucket_for_owner("default-owner", "bucket", false)
            .unwrap();

        let metadata = MetadataBlob::new();
        let create = coord
            .create_multipart_upload(&CreateMultipartUploadRequest {
                object: object_request_with_expected_owner("bucket", "key", test_requester(), None),
                metadata: &metadata,
                system_metadata: &SystemMetadata::EMPTY,
                tags: None,
                checksum: None,

                acl: NO_PUT_OBJECT_ACL.into(),
                encryption: WriteEncryptionRequest::none(),
                object_lock: ObjectLockState::default(),
                policy_context: PutObjectPolicyContext::default(),
            })
            .unwrap();

        // First abort succeeds.
        coord
            .abort_multipart_upload(&multipart_object_request_with_expected_owner(
                "bucket",
                "key",
                &create.upload_id,
                test_requester(),
                None,
            ))
            .unwrap();

        // Second abort: upload is already deleted, returns UploadNotFound.
        let err = coord
            .abort_multipart_upload(&multipart_object_request_with_expected_owner(
                "bucket",
                "key",
                &create.upload_id,
                test_requester(),
                None,
            ))
            .unwrap_err();
        assert!(
            matches!(err, ServerError::NoSuchUpload { .. }),
            "expected UploadNotFound on second abort, got {err:?}"
        );
    }

